import React, { useReducer } from 'react'
import { TeamContextProvider } from '../../context'
import reducer from '../../state/reducer'
import GroupUsersContainer from './containers'

function GroupUsers (props) {
  return (
    <TeamContextProvider value={useReducer(reducer, {})}>
      <GroupUsersContainer {...props} />
    </TeamContextProvider>
  )
}

export default GroupUsers
