import { Button, Icon, Popconfirm } from 'antd'

export const groupUsersColumns = ({ groupName, roleId, removeUserFromGroupRequest }) => ([
  {
    title: 'User',
    dataIndex: 'name',
    width: 250,
    render: name => <span style={{ wordBreak: 'break-word' }}>{name}</span>
  },
  {
    title: 'Email',
    dataIndex: 'email',
    width: 250,
    render: email => <span style={{ wordBreak: 'break-word' }}>{email}</span>
  },
  {
    title: 'Actions',
    align: 'right',
    width: 300,
    render: user => (
      <Popconfirm
        title={
          <div style={{ width: 250 }}>
            {`Are you sure you want to remove user '${user.name}', from the group '${groupName}'?`}
          </div>
          }
        onConfirm={() => removeUserFromGroupRequest({ group_id: roleId, user_id: user.id })}
      >
        <Button type='danger'>
          <Icon type='stop' /> Remove From Group
        </Button>
      </Popconfirm>
    )
  }
])
