/* eslint-disable react-hooks/exhaustive-deps */

import { useErrorContextValue, useLoaderContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import { Alert, Form, message, Modal, Select, Spin } from 'antd'
import React, { useCallback, useEffect, useMemo } from 'react'
import { useRoles, useUserContext } from '../../../../../state/hooks/useTeamContext'

const ManageGroupPermissions = ({ visible, form, roleName, roleId, roleUsers, closeModal }) => {
  const { getFieldDecorator } = form
  const { addUserToGroupRequest, getGroupUsers } = useRoles()
  const [{ ADD_USER_TO_GROUP_ERROR, addUserToGroupStatus }] = useErrorContextValue()
  const { getUserList, userListData } = useUserContext()
  const [{ USER_LIST_LOADER, ADD_USER_TO_GROUP_LOADER }] = useLoaderContextValue()
  const { resetError } = useResetError()

  const usersNotInThisRole = useMemo(() => {
    if (Array.isArray(userListData) && Array.isArray(roleUsers)) {
      return userListData.filter(user => !roleUsers.map(roleUser => roleUser.id).includes(user.id))
    }
  }, [userListData, roleUsers])

  const handleSubmit = useCallback(() => {
    form.validateFields((err, values) => {
      if (!err) {
        addUserToGroupRequest({ group_id: roleId, ...values })
      }
    })
  }, [])

  useEffect(() => {
    if (addUserToGroupStatus === 'success') {
      getGroupUsers({ group_name: roleName })
      message.success('User added to group successfully')
      resetError(['addUserToGroupStatus', 'ADD_USER_TO_GROUP_ERROR'])
      closeModal()
    }
  }, [addUserToGroupStatus])

  useEffect(() => {
    getUserList()
  }, [])

  return (
    <Modal
      title={`Add User To Role - ${roleName}`}
      visible={visible}
      onCancel={closeModal}
      okText='Update'
      onOk={handleSubmit}
    >
      {(ADD_USER_TO_GROUP_ERROR) && <Alert type='error' message={addUserToGroupStatus} banner />}
      <Spin spinning={!!ADD_USER_TO_GROUP_LOADER}>
        <Form>
          <Form.Item
            label='Group Users'
          >
            {
              getFieldDecorator('user_id', {})(
                <Select
                  loading={USER_LIST_LOADER}
                  showSearch
                  optionFilterProp='children'
                  filterOption={(input: any, option: any) => option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
                >
                  {
                    Array.isArray(usersNotInThisRole) && usersNotInThisRole.map(user => (
                      <Select.Option key={user.id} value={user.id}>
                        {user.name ? `${user.name}, ${user.email}` : `${user.email}`}
                      </Select.Option>
                    ))
                  }
                </Select>
              )
            }
          </Form.Item>
        </Form>
      </Spin>
    </Modal>
  )
}
export default Form.create({ name: 'group-users' })(ManageGroupPermissions)
