/* eslint-disable react-hooks/exhaustive-deps */
import React, { useCallback, useEffect, useState } from 'react'
import { useHistory, useParams } from 'react-router'
import { Button, Table, Col, Icon, Alert, Spin, Empty, Input, message } from 'antd'
import { groupUsersColumns } from './utility'
import EbEmptyPage from '../../../../../../components/EbEmptyPage/ebEmptypage'
import { RowWithMargin } from '../../../../EmployeeBenefits/CommonComponents'
import { ColTextAlignRight } from '../../../../EmployeeBenefits/CommonComponents/index.style'
import { useRoles } from '../../../state/hooks/useTeamContext'
import { useErrorContextValue, useLoaderContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import PermissionCheckerV2 from '../../../../../../components/permissionCheckerV2'
import ManageGroupUsers from './components/ManageGroupUsers'

const { Search } = Input

const GroupUsers = () => {
  const history = useHistory()
  const { roleName } = useParams()
  const [searchText, setSearchText] = useState(null)
  const [manageGroupUsersModalVisibility, toggleManageGroupUsersModalVisibility] = useState(false)
  const { getGroupUsers, groupUsersData, removeUserFromGroupRequest, resetState } = useRoles()
  const [{ GROUP_USERS_LOADER, REMOVE_USER_FROM_GROUP_LOADER }] = useLoaderContextValue()
  const [{ GROUP_USERS_ERROR, groupUsersStatus, REMOVE_USER_FROM_GROUP_ERROR, removeUserFromGroupStatus }] = useErrorContextValue()
  const { resetError } = useResetError()

  const getFilteredData = useCallback(() => {
    if (Array.isArray(groupUsersData) && groupUsersData.length) {
      const groupUsersList = groupUsersData[0].users
      if (searchText) {
        return groupUsersList.filter(user => new RegExp(searchText, 'i').test(user.name) || new RegExp(searchText, 'i').test(user.email))
      }
      return groupUsersList
    }
    return []
  }, [groupUsersData, searchText])

  useEffect(() => {
    if (removeUserFromGroupStatus === 'success') {
      message.success('User removed successfully')
      getGroupUsers({ group_name: roleName })
      resetError(['removeUserFromGroupStatus', 'REMOVE_USER_FROM_GROUP_ERROR'])
    }
  }, [removeUserFromGroupStatus])

  useEffect(() => {
    getGroupUsers({ group_name: roleName })
    return () => {
      resetState([
        'groupUsersData'
      ])
      resetError([
        'groupUsersStatus',
        'GROUP_USERS_ERROR'
      ])
    }
  }, [])

  return (
    <EbEmptyPage
      history={history}
    >
      <Spin spinning={!!GROUP_USERS_LOADER || !!REMOVE_USER_FROM_GROUP_LOADER}>
        {(GROUP_USERS_ERROR) && <Alert type='error' message={groupUsersStatus} banner />}
        {(REMOVE_USER_FROM_GROUP_ERROR) && <Alert type='error' message={removeUserFromGroupStatus} banner />}
        <RowWithMargin type='flex' justify='space-between'>
          <Col span={10}>
            <h2>{roleName} - Users</h2>
          </Col>
          <Col span={6}>
            <Search
              placeholder='Search..'
              onChange={(e) => setSearchText(e.target.value)}
              disabled={!groupUsersData?.length}
              allowClear
            />
          </Col>
          <PermissionCheckerV2 requiredPermission='ops.can_perform_team_actions'>
            <ColTextAlignRight
              span={6}
            >
              <Button
                type='primary'
                onClick={() => toggleManageGroupUsersModalVisibility(true)}
              >
                <Icon type='user-add' />
                Manage Group Users
              </Button>
            </ColTextAlignRight>
          </PermissionCheckerV2>
        </RowWithMargin>
        {
          Array.isArray(groupUsersData)
            ? (
              <Table
                columns={groupUsersColumns({
                  groupName: roleName,
                  removeUserFromGroupRequest,
                  roleId: Array.isArray(groupUsersData) ? groupUsersData[0]?.id : undefined
                })}
                dataSource={getFilteredData()}
                rowKey={(rowData) => rowData.id}
              />
              )
            : <Empty />
        }
      </Spin>
      {
        manageGroupUsersModalVisibility && (
          <ManageGroupUsers
            visible
            closeModal={() => toggleManageGroupUsersModalVisibility(false)}
            roleName={roleName}
            roleId={Array.isArray(groupUsersData) ? groupUsersData[0]?.id : undefined}
            roleUsers={Array.isArray(groupUsersData) && groupUsersData[0].users}
          />
        )
      }
    </EbEmptyPage>
  )
}

export default GroupUsers
